/* Tool 60 — CLMM impermanent loss: a composition of Tool 17 at the entry
   and exit ticks, cross-validated three ways in a foreground prototype
   before pinning — a 20,000-case sweep found the position value never
   above the hold value (max IL exactly 0 at no move), the symmetric
   range's two bound exits agreed to 1e-13, and the near-full-range
   case converged to Tool 4's constant-product figure to 1e-10. */
const cil1 = app.clmmImpermanentLoss("1000000", -600, 600, 0, 1200);
check("cil: headline — entry at tick 0 holds ~29,553 of each token", cil1 && Math.abs(cil1.entryAmount0 - 29553.010879133868) < 0.001 && Math.abs(cil1.entryAmount1 - 29553.010879133977) < 0.001 && cil1.exitStatus === "above");
near("cil: headline position value in token1", cil1 && cil1.positionValueToken1, 60005.99925504324, 0.001);
near("cil: headline hold value in token1", cil1 && cil1.holdValueToken1, 62873.73768841475, 0.001);
near("cil: headline impermanent loss is -4.561107%", cil1 && cil1.ilPct, -4.561107, 1e-4);
near("cil: headline shortfall is the hold minus the position value", cil1 && cil1.shortfallToken1, 2867.738433371509, 0.001);
check("cil: amounts are Tool 17's runs verbatim at both ticks", (() => { const e = app.clmmPosition("1000000", -600, 600, 0); const x = app.clmmPosition("1000000", -600, 600, 1200); return cil1 && cil1.entryAmount0 === e.amount0 && cil1.entryAmount1 === e.amount1 && cil1.exitAmount0 === x.amount0 && cil1.exitAmount1 === x.amount1 && cil1.positionValueToken1 === x.valueInToken1; })());
check("cil: no price move loses exactly zero", (() => { const r = app.clmmImpermanentLoss("1000000", -600, 600, 250, 250); return r && r.ilPct === 0 && r.shortfallToken1 === 0; })());
near("cil: an exit still in range (tick 300) loses -0.380598%", (app.clmmImpermanentLoss("1000000", -600, 600, 0, 300) || {}).ilPct, -0.380598, 1e-4);
